    // but we'll implement the logic as requested
    
    let n = n as i32;  // Convert to i32 to handle 4-digit numbers
    
    // Extract individual digits
    let thousands = (n / 1000) % 10;
    let hundreds = (n / 100) % 10;
    let tens = (n / 10) % 10;
    let ones = n % 10;
    
